    24	    public static void main(String[] args) {
    25	        // Configuração
    26	        String dbUrl = Environment.getDbUrl();
    27	        String dbUser = Environment.getDbUser();
    28	        String dbPassword = Environment.getDbPassword();
    29	        int port = Environment.getPort();
