    51	        RoomService roomService = new RoomService(roomRepository);
    52	        MessageService messageService = new MessageService(messageRepository, messagePipeline);
    53	        ReservationService reservationService = new ReservationService(
    54	            reservationRepository, roomService, pricingService, messageService
    55	        );
    56	        ReportService reportService = new ReportService(reservationRepository, roomRepository);
