    61	        MessageController messageController = new MessageController(messageService);
    62	        ReportController reportController = new ReportController(reportService);
    63	
    64	        // Javalin app
    65	        Javalin app = Javalin.create(config -> {
    66	            config.bundledPlugins.enableCors(cors -> {
    67	                cors.addRule(it -> {
    68	                    it.anyHost();
    69	                });
    70	            });
    71	        });
    72	
    73	        // Routes
    74	        app.get("/rooms", roomController::getRooms);
    75	        app.post("/reservations", reservationController::createReservation);
    76	        app.get("/reservations/{id}", reservationController::getReservation);
    77	        app.post("/reservations/{id}/confirmation", reservationController::confirmReservation);
    78	        app.post("/reservations/{id}/cancellation", reservationController::cancelReservation);
    79	        app.post("/reservations/{id}/check-in", reservationController::checkIn);
    80	        app.post("/reservations/{id}/check-out", reservationController::checkOut);
    81	        app.get("/reservations/{id}/document", reservationController::getDocument);
    82	        app.get("/messages", messageController::getMessages);
    83	        app.get("/reports/occupancy", reportController::getOccupancyReport);
    84	        app.get("/reports/revenue", reportController::getRevenueReport);
    85	
