    21	    public ReservationController(ReservationService reservationService, RoomService roomService) {
    22	        this.reservationService = reservationService;
    23	        this.roomService = roomService;
    24	    }
    25	
    26	    public void createReservation(Context ctx) {
    27	        try {
    28	            CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
    29	
    30	            // Validações básicas
    31	            if (request.roomNumber() == null || request.guestName() == null ||
    32	                request.guestEmail() == null || request.guestCpf() == null ||
    33	                request.checkIn() == null || request.checkOut() == null ||
    34	                request.ratePlan() == null) {
    35	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing required fields"));
    36	                return;
    37	            }
    38	
    39	            if (request.guests() < 1) {
    40	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Number of guests must be at least 1"));
    41	                return;
    42	            }
    43	
    44	            LocalDate checkIn;
    45	            LocalDate checkOut;
    46	            try {
    47	                checkIn = LocalDate.parse(request.checkIn());
    48	                checkOut = LocalDate.parse(request.checkOut());
    49	            } catch (DateTimeParseException e) {
    50	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
    51	                return;
    52	            }
    53	
    54	            if (!checkOut.isAfter(checkIn)) {
    55	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Check-out must be after check-in"));
    56	                return;
    57	            }
    58	
    59	            RatePlan ratePlan;
    60	            try {
    61	                ratePlan = RatePlan.valueOf(request.ratePlan());
    62	            } catch (IllegalArgumentException e) {
    63	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid rate plan"));
    64	                return;
    65	            }
    66	
    67	            Reservation reservation = new Reservation();
    68	            reservation.setRoomNumber(request.roomNumber());
    69	            reservation.setGuestName(request.guestName());
    70	            reservation.setGuestEmail(request.guestEmail());
    71	            reservation.setGuestCpf(request.guestCpf());
    72	            reservation.setCheckIn(checkIn);
    73	            reservation.setCheckOut(checkOut);
    74	            reservation.setGuests(request.guests());
    75	            reservation.setRatePlan(ratePlan);
    76	
    77	            Reservation created = reservationService.createReservation(reservation);
    78	            ctx.status(201).json(ReservationResponse.from(created));
    79	
    80	        } catch (ReservationService.RoomNotFoundException e) {
    81	            ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", "Room not found"));
    82	        } catch (ReservationService.RoomUnavailableException e) {
    83	            ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", "Room is not available for these dates"));
    84	        } catch (ReservationService.CapacityExceededException e) {
    85	            ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", "Number of guests exceeds room capacity"));
    86	        }
    87	    }
