     1	package com.pousada.marealta.service;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.time.LocalDate;
     6	
     7	/**
     8	 * Serviço de cálculo de preços com suporte a alta temporada e arredondamento bancário.
     9	 *
    10	 * Alta temporada (20% adicional):
    11	 * - 15 de dezembro até fim de fevereiro
    12	 * - Mês de julho inteiro
    13	 *
    14	 * Arredondamento: "meio para o par" (banker's rounding / HALF_EVEN)
    15	 */
    16	public class PricingService {
    17	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
    18	    private static final int SCALE = 2;
    19	
    20	    public boolean isHighSeason(LocalDate date) {
    21	        int month = date.getMonthValue();
    22	        int day = date.getDayOfMonth();
    23	
    24	        // Julho inteiro
    25	        if (month == 7) {
    26	            return true;
    27	        }
    28	
    29	        // Dezembro (a partir do dia 15)
    30	        if (month == 12 && day >= 15) {
    31	            return true;
    32	        }
    33	
    34	        // Janeiro e fevereiro inteiros
    35	        if (month == 1 || month == 2) {
    36	            return true;
    37	        }
    38	
    39	        return false;
    40	    }
    41	
    42	    public BigDecimal calculateNightPrice(BigDecimal baseRate, LocalDate night) {
    43	        BigDecimal price = baseRate;
    44	        if (isHighSeason(night)) {
    45	            price = price.multiply(HIGH_SEASON_MULTIPLIER);
    46	        }
    47	        return round(price);
    48	    }
    49	
    50	    public BigDecimal round(BigDecimal value) {
    51	        return value.setScale(SCALE, RoundingMode.HALF_EVEN);
    52	    }
    53	}
