    22	
    23	    public String generateOccupancyReport(LocalDate date) {
    24	        List<Reservation> reservations = reservationRepository.findByNight(date);
    25	        List<Room> allRooms = roomRepository.findAll();
    26	
    27	        StringBuilder csv = new StringBuilder();
    28	        csv.append("room,type,reservation,check_in,check_out\n");
    29	
    30	        for (Reservation r : reservations) {
    31	            Room room = roomRepository.findByNumber(r.getRoomNumber());
    32	            csv.append(r.getRoomNumber()).append(",");
    33	            csv.append(room.getType()).append(",");
    34	            csv.append(r.getId()).append(",");
    35	            csv.append(r.getCheckIn().format(DateTimeFormatter.ISO_LOCAL_DATE)).append(",");
    36	            csv.append(r.getCheckOut().format(DateTimeFormatter.ISO_LOCAL_DATE)).append("\n");
    37	        }
    38	
    39	        csv.append("total,").append(reservations.size()).append("/").append(allRooms.size());
    40	
    41	        return csv.toString();
    42	    }
    43	
    44	    public String generateRevenueReport(YearMonth month) {
    45	        List<Reservation> reservations = reservationRepository.findByMonth(month);
    46	
    47	        StringBuilder csv = new StringBuilder();
    48	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    49	
    50	        BigDecimal total = BigDecimal.ZERO;
    51	
    52	        for (Reservation r : reservations) {
    53	            // Dinheiro que ficou com a pousada = pago - reembolsado
    54	            BigDecimal amount = r.getAmountPaid();
    55	            if (r.getRefund() != null) {
    56	                amount = amount.subtract(r.getRefund());
    57	            }
    58	
    59	            // Só conta se ficou algum dinheiro
    60	            if (amount.compareTo(BigDecimal.ZERO) > 0) {
    61	                csv.append(r.getId()).append(",");
    62	                csv.append(r.getRoomNumber()).append(",");
    63	                csv.append(r.getCheckIn().format(DateTimeFormatter.ISO_LOCAL_DATE)).append(",");
    64	                csv.append(r.getCheckOut().format(DateTimeFormatter.ISO_LOCAL_DATE)).append(",");
    65	                csv.append(r.getStatus()).append(",");
    66	                csv.append(formatCsvMoney(amount)).append("\n");
    67	
    68	                total = total.add(amount);
    69	            }
    70	        }
    71	
    72	        csv.append("total,").append(formatCsvMoney(total));
    73	
    74	        return csv.toString();
    75	    }
    76	
    77	    private String formatCsvMoney(BigDecimal amount) {
    78	        return amount.toString();
    79	    }
    80	}
