   185	        sb.append("Hóspede: ").append(reservation.getGuestName());
   186	        sb.append(" (CPF ").append(formatCpf(reservation.getGuestCpf())).append(")\n");
   187	        sb.append("Quarto: ").append(reservation.getRoomNumber());
   188	        sb.append(" (").append(room.getType()).append(")\n");
   189	        sb.append("Entrada: ").append(formatDate(reservation.getCheckIn()));
   190	        sb.append(" | Saída: ").append(formatDate(reservation.getCheckOut()));
   191	        sb.append(" | ").append(reservation.getNights());
   192	        sb.append(reservation.getNights() == 1 ? " diária" : " diárias").append("\n");
   193	        sb.append("Diárias: ").append(formatMoney(reservation.getSubtotal())).append("\n");
   194	
   195	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
   196	            sb.append("Desconto: ").append(formatMoney(reservation.getDiscount())).append("\n");
   197	        }
   198	
   199	        sb.append("Total: ").append(formatMoney(reservation.getTotal()));
