    10	/**
    11	 * Regra que valida endereços de e-mail e bloqueia mensagens para endereços inválidos.
    12	 *
    13	 * Um e-mail é válido quando:
    14	 * - Tem um único @
    15	 * - Tem algo antes do @
    16	 * - Depois do @, tem um domínio com pelo menos um ponto (ex: gmail.com)
    17	 */
    18	public class ValidateEmailRule implements MessageRule {
    19	
    20	    @Override
    21	    public List<Message> process(Message message) {
    22	        if (!isValidEmail(message.getTo())) {
    23	            message.setStatus(MessageStatus.BLOCKED);
    24	        }
    25	        return Collections.singletonList(message);
    26	    }
    27	
    28	    private boolean isValidEmail(String email) {
    29	        if (email == null || email.isEmpty()) {
    30	            return false;
    31	        }
    32	
    33	        int atCount = 0;
    34	        int atPosition = -1;
    35	
    36	        for (int i = 0; i < email.length(); i++) {
    37	            if (email.charAt(i) == '@') {
    38	                atCount++;
    39	                atPosition = i;
    40	            }
    41	        }
    42	
    43	        // Deve ter exatamente um @
    44	        if (atCount != 1) {
    45	            return false;
    46	        }
    47	
    48	        // Deve ter algo antes do @
    49	        if (atPosition == 0) {
    50	            return false;
    51	        }
    52	
    53	        // Deve ter algo depois do @
    54	        String domain = email.substring(atPosition + 1);
    55	        if (domain.isEmpty()) {
    56	            return false;
    57	        }
    58	
    59	        // O domínio deve ter pelo menos um ponto
    60	        if (!domain.contains(".")) {
    61	            return false;
    62	        }
    63	
    64	        // O ponto não pode ser no início ou fim do domínio
    65	        if (domain.startsWith(".") || domain.endsWith(".")) {
    66	            return false;
    67	        }
    68	
    69	        return true;
    70	    }
    71	}

