    27	    public Reservation createReservation(Reservation reservation) {
    28	        // Valida que o quarto existe
    29	        Room room = roomService.getRoomByNumber(reservation.getRoomNumber());
    30	        if (room == null) {
    31	            throw new RoomNotFoundException();
    32	        }
    33	
    34	        // Valida capacidade
    35	        if (reservation.getGuests() > room.getCapacity()) {
    36	            throw new CapacityExceededException();
    37	        }
    38	
    39	        // Valida disponibilidade
    40	        List<Reservation> conflicts = reservationRepository.findConflictingReservations(
    41	            reservation.getRoomNumber(),
    42	            reservation.getCheckIn(),
    43	            reservation.getCheckOut(),
    44	            null
    45	        );
    46	        if (!conflicts.isEmpty()) {
    47	            throw new RoomUnavailableException();
    48	        }
    49	
    50	        // Calcula preços
    51	        calculatePricing(reservation, room);
    52	
    53	        // Salva
    54	        return reservationRepository.save(reservation);
    55	    }
    56	
    57	    private void calculatePricing(Reservation reservation, Room room) {
    58	        int nights = (int) ChronoUnit.DAYS.between(reservation.getCheckIn(), reservation.getCheckOut());
    59	        reservation.setNights(nights);
    60	
    61	        // Calcula o preço de cada noite e soma
    62	        BigDecimal subtotal = BigDecimal.ZERO;
    63	        LocalDate currentNight = reservation.getCheckIn();
    64	        for (int i = 0; i < nights; i++) {
    65	            BigDecimal nightPrice = pricingService.calculateNightPrice(room.getNightlyRate(), currentNight);
    66	            subtotal = subtotal.add(nightPrice);
    67	            currentNight = currentNight.plusDays(1);
    68	        }
    69	        subtotal = pricingService.round(subtotal);
    70	        reservation.setSubtotal(subtotal);
    71	
    72	        // Calcula desconto se aplicável
    73	        BigDecimal discount = BigDecimal.ZERO;
    74	        if (reservation.getRatePlan() == RatePlan.NON_REFUNDABLE) {
    75	            discount = subtotal.multiply(new BigDecimal("0.15"));
    76	            discount = pricingService.round(discount);
    77	        }
    78	        reservation.setDiscount(discount);
    79	
    80	        // Calcula total
    81	        BigDecimal total = subtotal.subtract(discount);
    82	        total = pricingService.round(total);
    83	        reservation.setTotal(total);
    84	    }
