   204	    private String formatCpf(String cpf) {
   205	        // Remove tudo que não é dígito
   206	        String digits = cpf.replaceAll("\\D", "");
   207	        if (digits.length() == 11) {
   208	            return digits.substring(0, 3) + "." +
   209	                   digits.substring(3, 6) + "." +
   210	                   digits.substring(6, 9) + "-" +
   211	                   digits.substring(9);
   212	        }
   213	        return cpf;
