     7	/**
     8	 * Pipeline de processamento de mensagens que aplica múltiplas regras em sequência.
     9	 * Cada regra pode modificar, bloquear ou criar cópias de mensagens.
    10	 */
    11	public class MessagePipeline {
    12	    private final List<MessageRule> rules;
    13	
    14	    public MessagePipeline(List<MessageRule> rules) {
    15	        this.rules = rules;
    16	    }
    17	
    18	    /**
    19	     * Processa uma mensagem através de todas as regras configuradas.
    20	     *
    21	     * @param message Mensagem original
    22	     * @return Lista de todas as mensagens geradas (original modificada + cópias)
    23	     */
    24	    public List<Message> process(Message message) {
    25	        List<Message> messages = new ArrayList<>();
    26	        messages.add(message);
    27	
    28	        for (MessageRule rule : rules) {
    29	            List<Message> processedMessages = new ArrayList<>();
    30	            for (Message msg : messages) {
    31	                processedMessages.addAll(rule.process(msg));
    32	            }
    33	            messages = processedMessages;
    34	        }
    35	
    36	        return messages;
    37	    }
    38	}
