    11	/**
    12	 * Regra que cria cópia de mensagens para arquivo.
    13	 *
    14	 * Para cada mensagem enviada (não bloqueada):
    15	 * - Cria cópia para arquivo@pousadamarealta.com.br
    16	 * - Assunto recebe prefixo "[Cópia] "
    17	 * - Corpo permanece o mesmo
    18	 */
    19	public class ArchiveCopyRule implements MessageRule {
    20	    private static final String ARCHIVE_EMAIL = "arquivo@pousadamarealta.com.br";
    21	    private static final String COPY_PREFIX = "[Cópia] ";
    22	
    23	    private final boolean enabled;
    24	
    25	    public ArchiveCopyRule(boolean enabled) {
    26	        this.enabled = enabled;
    27	    }
    28	
    29	    @Override
    30	    public List<Message> process(Message message) {
    31	        if (!enabled) {
    32	            return Collections.singletonList(message);
    33	        }
    34	
    35	        // Não cria cópia de mensagens bloqueadas
    36	        if (message.getStatus() == MessageStatus.BLOCKED) {
    37	            return Collections.singletonList(message);
    38	        }
    39	
    40	        List<Message> messages = new ArrayList<>();
    41	        messages.add(message);
    42	
    43	        // Cria cópia para arquivo
    44	        Message copy = new Message();
    45	        copy.setChannel(message.getChannel());
    46	        copy.setTo(ARCHIVE_EMAIL);
    47	        copy.setSubject(COPY_PREFIX + message.getSubject());
    48	        copy.setBody(message.getBody());
    49	        copy.setStatus(MessageStatus.SENT);
    50	
    51	        messages.add(copy);
    52	
    53	        return messages;
    54	    }
