    30	    private Reservation insert(Reservation reservation) {
    31	        String sql = """
    32	            INSERT INTO reservations
    33	            (room_number, guest_name, guest_email, guest_cpf, check_in, check_out,
    34	             guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund)
    35	            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    36	            RETURNING id
    37	        """;
    38	
    39	        try (Connection conn = database.getConnection();
    40	             PreparedStatement stmt = conn.prepareStatement(sql)) {
    41	
    42	            setReservationParameters(stmt, reservation);
    43	            try (ResultSet rs = stmt.executeQuery()) {
    44	                if (rs.next()) {
    45	                    reservation.setId(rs.getLong("id"));
    46	                }
    47	            }
    48	        } catch (SQLException e) {
    49	            throw new RuntimeException("Error inserting reservation", e);
    50	        }
    51	
    52	        return reservation;
    53	    }
    54	
    55	    private Reservation update(Reservation reservation) {
    56	        String sql = """
    57	            UPDATE reservations SET
    58	                room_number = ?, guest_name = ?, guest_email = ?, guest_cpf = ?,
    59	                check_in = ?, check_out = ?, guests = ?, rate_plan = ?,
    60	                nights = ?, subtotal = ?, discount = ?, total = ?,
    61	                status = ?, amount_paid = ?, refund = ?
    62	            WHERE id = ?
    63	        """;
    64	
    65	        try (Connection conn = database.getConnection();
